 * @return {number}
 */
var minPairSum = function(nums) {
    nums.sort((a, b) => a - b);

    const n = nums.length;
    let max = -Infinity;

    for (let i = 0; i <= n / 2; i++) {
        max = Math.max(max, nums[i] + nums[n - 1 - i]);
    }

    return max;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minPairSum = function(nums) {
    nums.sort((a, b) => a - b);

    const n = nums.length;
    const len = n / 2;
    let max = -Infinity;

    for (let i = 0; i < len; i++) {
        const sum = nums[i] + nums[n - 1 - i];

        if (sum > max) {
            max = sum;
        }
    }

    return max;
};
